#!/usr/bin/env node
// Claude Code PostToolUse hook (Edit, Write, MultiEdit) — generated by KeelWright.
// Formats the edited file with Prettier and fixes it with ESLint, using the project's own
// binaries. Lint errors that can't be fixed automatically are shown to Claude (exit 2) so it
// fixes them in the same turn. Does nothing for files the tools don't handle.

import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { join, relative, resolve } from 'node:path';

const LINTABLE = /\.(?:[cm]?[jt]sx?|astro|vue|svelte)$/;

let input = null;
try {
  input = JSON.parse(readFileSync(0, 'utf8'));
} catch {
  process.exit(0);
}
const filePath = input?.tool_input?.file_path;
if (!filePath) process.exit(0);
const root = process.env.CLAUDE_PROJECT_DIR ?? input.cwd ?? process.cwd();
const file = resolve(root, filePath);
const rel = relative(root, file);
if (!existsSync(file) || rel.startsWith('..') || /(^|\/)(node_modules|dist|\.git)\//.test(rel)) process.exit(0);

const bin = (name) => {
  const p = join(root, 'node_modules', '.bin', name);
  return existsSync(p) ? p : null;
};
const run = (cmd, args) => spawnSync(cmd, args, { cwd: root, encoding: 'utf8', timeout: 60_000 });

const prettier = bin('prettier');
if (prettier) run(prettier, ['--write', '--ignore-unknown', '--log-level', 'warn', file]);

const eslint = bin('eslint');
if (eslint && LINTABLE.test(file)) {
  const r = run(eslint, ['--fix', '--no-warn-ignored', '--max-warnings=0', file]);
  if (r.status === 1) {
    process.stderr.write(`ESLint found problems in ${rel} that need a manual fix:\n${(r.stdout || r.stderr).trim()}\n`);
    process.exit(2);
  }
}
process.exit(0);
